-- changeset marcopremier:17 dbms:cloudspanner
-- comment: Persist raw-impression upload correction candidates and fence state.

SET PROTO_DESCRIPTORS = '';

START BATCH DDL;

ALTER PROTO BUNDLE INSERT (
  `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.Classification`,
  `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.State`,
  `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.Decision`,
  `wfa.measurement.internal.edpaggregator.VidLabelingEvictionFenceState`
) UPDATE (
  `wfa.measurement.internal.edpaggregator.RawImpressionUploadState`
);

ALTER TABLE VidLabelingEvictionFence ADD COLUMN State
  `wfa.measurement.internal.edpaggregator.VidLabelingEvictionFenceState`;

CREATE TABLE RawImpressionUploadCorrectionCandidate (
  DataProviderResourceId STRING(63) NOT NULL,
  RawImpressionUploadCorrectionCandidateId STRING(36) NOT NULL,
  RawImpressionUploadResourceId STRING(63) NOT NULL,
  CreateRequestId STRING(36) NOT NULL,
  Classification `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.Classification` NOT NULL,
  PriorManifestDigest BYTES(MAX) NOT NULL,
  CurrentManifestDigest BYTES(MAX) NOT NULL,
  State `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.State` NOT NULL,
  Decision `wfa.measurement.internal.edpaggregator.RawImpressionUploadCorrectionCandidate.Decision` NOT NULL,
  SupersedingRawImpressionUploadCorrectionCandidateId STRING(36),
  UploadHealingOperationId STRING(36),
  ExpireTime TIMESTAMP NOT NULL,
  AdvanceRequestIds ARRAY<STRING(36)> NOT NULL,
  AdvanceRequestFingerprints ARRAY<BYTES(MAX)> NOT NULL,
  CreateTime TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
  UpdateTime TIMESTAMP NOT NULL OPTIONS (allow_commit_timestamp = true),
) PRIMARY KEY (DataProviderResourceId, RawImpressionUploadCorrectionCandidateId);

CREATE UNIQUE INDEX RawImpressionUploadCorrectionCandidateByRawImpressionUpload
  ON RawImpressionUploadCorrectionCandidate(DataProviderResourceId, RawImpressionUploadResourceId);

CREATE UNIQUE INDEX RawImpressionUploadCorrectionCandidateByCreateRequestId
  ON RawImpressionUploadCorrectionCandidate(DataProviderResourceId, CreateRequestId);

CREATE INDEX RawImpressionUploadCorrectionCandidateByStateAndCreateTime
  ON RawImpressionUploadCorrectionCandidate(DataProviderResourceId, State, CreateTime, RawImpressionUploadCorrectionCandidateId);

RUN BATCH;
